        now
      }),
    /reservationId is required/
  );

  assert.throws(
    () =>
      service.reserveStock({
        reservationId: "R-1",
        orderId: "",
        lines: [{ skuId: "A", quantity: 1 }],
        ttlMinutes: 15,
        now
      }),
    /orderId is required/
  );

  assert.throws(
    () =>
      service.reserveStock({
        reservationId: "R-1",
