        now
      }),
    /ttlMinutes must be a positive integer/
  );

  assert.throws(
    () =>
      service.reserveStock({
        reservationId: "R-1",
        orderId: "O-1",
        lines: [{ skuId: "A", quantity: 0 }],
        ttlMinutes: 15,
        now
      }),
    /quantity must be a positive integer/
  );

  const first = service.reserveStock({
    reservationId: "R-1",
    orderId: "O-1",
    lines: [{ skuId: "A", quantity: 2 }],
    ttlMinutes: 15,
    now
  });

  assert.equal(first.ok, true);
  assert.equal(repository.load().stockBySku.A, 3);

  assert.throws(
    () =>
      service.reserveStock({
        reservationId: "R-1",
        orderId: "O-2",
        lines: [{ skuId: "A", quantity: 1 }],
        ttlMinutes: 15,
        now
      }),
    /reservationId already exists/
  );

  assert.throws(
    () =>
      service.reserveStock({
        reservationId: "R-2",
        orderId: "O-1",
        lines: [{ skuId: "A", quantity: 1 }],
        ttlMinutes: 15,
        now
      }),
    /orderId already exists/
  );

  const shortage = service.reserveStock({
    reservationId: "R-3",
    orderId: "O-3",
    lines: [{ skuId: "A", quantity: 4 }],
    ttlMinutes: 15,
    now
  });

  assert.equal(shortage.ok, false);
  assert.deepEqual(shortage.shortages, [{ skuId: "A", quantity: 4, missing: 1 }]);
  assert.equal(repository.load().stockBySku.A, 3);
  assert.deepEqual(repository.load().events.map((event) => event.type), ["reservation-created"]);

  const beforeSave = repository.load();
  repository.save(beforeSave);
  const afterSave = repository.load();
  assert.deepEqual(afterSave.reservations, beforeSave.reservations);
  assert.deepEqual(afterSave.events, beforeSave.events);
});

