function positiveInteger(value, label) {
  if (!Number.isInteger(value) || value <= 0) throw new Error(`${label} must be a positive integer`);
  return value;
}

function requiredString(value, label) {
  const normalized = String(value ?? "").trim();
  if (normalized.length === 0) throw new Error(`${label} is required`);
  return normalized;
}

function normalizeLines(lines) {
  if (!Array.isArray(lines) || lines.length === 0) throw new Error("lines must not be empty");

  const seenSkuIds = new Set();
  return lines.map((line) => {
    const skuId = requiredString(line?.skuId, "skuId");
    if (seenSkuIds.has(skuId)) throw new Error("duplicate skuId");
    seenSkuIds.add(skuId);
    return {
      skuId,
      quantity: positiveInteger(line?.quantity, "quantity")
    };
  });
}

function normalizeNow(value) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.valueOf())) throw new Error("now must be a valid date");
  return date;
}

function clone(value) {
  return structuredClone(value);
}

function ensureReservationCollections(state) {
  if (!Array.isArray(state.orders)) state.orders = [];
  if (!Array.isArray(state.reservations)) state.reservations = [];
  if (!Array.isArray(state.events)) state.events = [];
}

function getReservation(state, reservationId) {
  return state.reservations.find((reservation) => reservation.reservationId === reservationId);
}

export function createWarehouseState(stockBySku = {}) {
  return {
    stockBySku: { ...stockBySku },
    orders: [],
    reservations: [],
    events: []
  };
}

export function allocateOrder(state, input) {
  ensureReservationCollections(state);
  const orderId = requiredString(input?.orderId, "orderId");
  if (state.orders.some((order) => order.orderId === orderId)) throw new Error("orderId already exists");
  const lines = normalizeLines(input?.lines);
  const shortages = lines
    .map((line) => ({ ...line, missing: Math.max(0, line.quantity - (state.stockBySku[line.skuId] ?? 0)) }))
    .filter((line) => line.missing > 0);
  if (shortages.length > 0) return { ok: false, shortages };

  for (const line of lines) state.stockBySku[line.skuId] -= line.quantity;
  const order = { orderId, lines: clone(lines), status: "allocated" };
  state.orders.push(order);
  state.events.push({ type: "order-allocated", orderId });
  return { ok: true, order };
}

export function reserveStock(state, input) {
  ensureReservationCollections(state);
  const reservationId = requiredString(input?.reservationId, "reservationId");
  const orderId = requiredString(input?.orderId, "orderId");
  if (state.reservations.some((reservation) => reservation.reservationId === reservationId)) {
    throw new Error("reservationId already exists");
  }
  if (state.orders.some((order) => order.orderId === orderId) || state.reservations.some((reservation) => reservation.orderId === orderId)) {
    throw new Error("orderId already exists");
  }

  const lines = normalizeLines(input?.lines);
  const ttlMinutes = positiveInteger(input?.ttlMinutes, "ttlMinutes");
  const now = normalizeNow(input?.now);
  const shortages = lines
    .map((line) => ({ ...line, missing: Math.max(0, line.quantity - (state.stockBySku[line.skuId] ?? 0)) }))
    .filter((line) => line.missing > 0);
  if (shortages.length > 0) return { ok: false, shortages };

  for (const line of lines) state.stockBySku[line.skuId] -= line.quantity;

  const reservation = {
    reservationId,
    orderId,
    lines: clone(lines),
    ttlMinutes,
    status: "active",
    createdAt: clone(now),
    expiresAt: new Date(now.getTime() + ttlMinutes * 60_000)
  };
  state.reservations.push(reservation);
  state.events.push({ type: "reservation-created", reservationId, orderId, expiresAt: clone(reservation.expiresAt) });
  return { ok: true, reservation: clone(reservation) };
}

export function confirmReservation(state, input) {
  ensureReservationCollections(state);
  const reservationId = requiredString(input?.reservationId, "reservationId");
  const reservation = getReservation(state, reservationId);
  if (!reservation) throw new Error("reservationId not found");
  if (reservation.status !== "active") throw new Error("reservation is not active");
  if (state.orders.some((order) => order.orderId === reservation.orderId)) throw new Error("orderId already exists");

  const order = {
    orderId: reservation.orderId,
    reservationId: reservation.reservationId,
    lines: clone(reservation.lines),
    status: "confirmed"
  };

  reservation.status = "confirmed";
  state.orders.push(order);
  state.events.push({ type: "reservation-confirmed", reservationId, orderId: reservation.orderId });
  return { ok: true, reservation: clone(reservation), order: clone(order) };
}

export function releaseExpired(state, input) {
  ensureReservationCollections(state);
  const now = normalizeNow(input?.now);
  const expiredAt = clone(now);
  const releasedReservations = [];

  for (const reservation of state.reservations) {
    if (reservation.status !== "active") continue;
    if (reservation.expiresAt.getTime() > now.getTime()) continue;

    for (const line of reservation.lines) {
      state.stockBySku[line.skuId] = (state.stockBySku[line.skuId] ?? 0) + line.quantity;
    }
    reservation.status = "expired";
    reservation.expiredAt = clone(expiredAt);
    releasedReservations.push(clone(reservation));
    state.events.push({ type: "reservation-expired", reservationId: reservation.reservationId, orderId: reservation.orderId });
  }

  return { ok: true, reservations: releasedReservations };
}

export function listReservations(state) {
  ensureReservationCollections(state);
  return clone(state.reservations);
}

export function restock(state, input) {
  ensureReservationCollections(state);
  const skuId = requiredString(input?.skuId, "skuId");
  const quantity = positiveInteger(input?.quantity, "quantity");
  state.stockBySku[skuId] = (state.stockBySku[skuId] ?? 0) + quantity;
  state.events.push({ type: "stock-restocked", skuId, quantity });
  return state.stockBySku[skuId];
}

