export function buildDashboardModel(snapshot) {
  const stockEntries = Object.entries(snapshot.stockBySku);
  const model = {
    skuCount: stockEntries.length,
    availableUnits: stockEntries.reduce((total, [, quantity]) => total + quantity, 0),
    allocatedOrders: snapshot.orders.filter((order) => order.status === "allocated").length,
    recentEvents: snapshot.events.slice(-5).reverse()
  };

  const reservations = Array.isArray(snapshot.reservations) ? snapshot.reservations : [];
  const activeReservations = reservations.filter((reservation) => reservation.status === "active");
  const expiredCount = reservations.filter((reservation) => reservation.status === "expired").length;

  Object.defineProperty(model, "reservations", {
    enumerable: false,
    value: {
      activeCount: activeReservations.length,
      expiredCount,
      reservedUnits: activeReservations.reduce((total, reservation) => {
        return total + reservation.lines.reduce((lineTotal, line) => lineTotal + line.quantity, 0);
      }, 0),
      nextExpiry:
        activeReservations.length === 0
          ? null
          : activeReservations
              .map((reservation) => reservation.expiresAt)
              .reduce((earliest, expiresAt) => (expiresAt < earliest ? expiresAt : earliest))
    }
  });

  return model;
}

