@@ -1,11 +1,35 @@
-export function createWarehouseApi(service) {
-  return {
-    allocateOrder: (body) => service.allocateOrder(body),
-    reserveStock: (body) => service.reserveStock(body),
-    confirmReservation: (body) => service.confirmReservation(body),
-    releaseExpired: (body) => service.releaseExpired(body),
-    listReservations: () => service.listReservations(),
-    restock: (body) => ({ quantity: service.restock(body) }),
-    getSnapshot: () => service.snapshot()
-  };
-}
+export function createWarehouseApi(service) {
+  function toIsoTimestamp(value) {
+    return value instanceof Date ? value.toISOString() : value;
+  }
+
+  function toPublicReservation(reservation) {
+    if (!reservation) return reservation;
+    const publicReservation = {
+      ...reservation,
+      createdAt: toIsoTimestamp(reservation.createdAt),
+      expiresAt: toIsoTimestamp(reservation.expiresAt)
+    };
+    if ("expiredAt" in reservation) publicReservation.expiredAt = toIsoTimestamp(reservation.expiredAt);
+    return publicReservation;
+  }
+
+  return {
+    allocateOrder: (body) => service.allocateOrder(body),
+    reserveStock: (body) => {
+      const result = service.reserveStock(body);
+      return result.ok ? toPublicReservation(result.reservation) : result;
+    },
+    confirmReservation: (body) => {
+      const result = service.confirmReservation(body);
+      return result.ok ? toPublicReservation(result.reservation) : result;
+    },
+    releaseExpired: (body) => {
+      const result = service.releaseExpired(body);
+      return result.reservations.map(toPublicReservation);
+    },
+    listReservations: () => service.listReservations().map(toPublicReservation),
+    restock: (body) => ({ quantity: service.restock(body) }),
+    getSnapshot: () => service.snapshot()
+  };
+}
